{
  "doneWhen": "6 parsnips planted and watered on tiles x7..9, y3..5",
  "modes": [
    {
      "macro": "skill",
      "params": { "name": "field-work" }
    }
  ],
  "skills": [
    {
      "name": "field-work",
      "skill": "async (b) => { const tiles = []; for (let y = 3; y <= 5; y++) { for (let x = 7; x <= 9; x++) { tiles.push({x, y}); } } for (const t of tiles) { b.log('working tile ' + t.x + ',' + t.y); let r = await b.workTile(t.x, t.y, 0, 'ControllerX'); b.log('till: ' + JSON.stringify(r)); r = await b.workTile(t.x, t.y, 2, 'ControllerA'); b.log('plant: ' + JSON.stringify(r)); r = await b.workTile(t.x, t.y, 1, 'ControllerX'); b.log('water: ' + JSON.stringify(r)); } return {ok: true, detail: 'worked ' + tiles.length + ' tiles'}; }",
      "check": "async (b) => { const body = await b.body(); const items = await b.items(); const seeds = items.find(i => i.name && i.name.toLowerCase().includes('parsnip')); const left = seeds ? seeds.stack : 0; return {ok: left === 0, detail: 'parsnip seeds left: ' + left}; }"
    }
  ]
}
